using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Experimental.Rendering;
internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        const string output = "Packages/VividRP/Roadmap~/Experiments/VSMCapacityCostDynamic_20260912/reference-update-gpu-result.txt";
        var owned = new List<UnityEngine.Object>();
        RayTracingAccelerationStructure acceleration = null;
        var cmd = new CommandBuffer();
        var report = new StringBuilder();
        int passed = 0, failed = 0;
        try
        {
            // Create only temporary current-scene GameObjects, then destroy them
            // synchronously in finally. No scene creation, switching or saving.
            var asset = AssetDatabase.LoadAssetAtPath<ComputeShader>(
                "Packages/com.vivid.render-pipelines/Editor/Tools/VSMBaselineReference.compute");
            if (asset==null) throw new Exception("Import the independent reference shader.");
            var reference = UnityEngine.Object.Instantiate(asset); owned.Add(reference);
            var errorMaterial = new Material(Shader.Find("Hidden/InternalErrorShader")); owned.Add(errorMaterial);
            var standardShader = Shader.Find("VividRP/Material/StandardLit");
            if(standardShader==null) throw new Exception("StandardLit fixture shader unavailable.");
            var standardMaterial = new Material(standardShader); owned.Add(standardMaterial);
            var depth = new Texture2D(1,1,TextureFormat.RFloat,false,true); owned.Add(depth);
            depth.SetPixelData(new float[]{.2f},0); depth.Apply();
            var normal = new Texture2D(1,1,TextureFormat.RGBAFloat,false,true); owned.Add(normal);
            normal.SetPixel(0,0,new Color(.5f,1,0,0)); normal.Apply();
            var shadow = new Texture2D(1,1,TextureFormat.RFloat,false,true); owned.Add(shadow);
            shadow.SetPixelData(new float[]{.3f},0); shadow.Apply();
            RenderTexture Output()
            {
                var value = new RenderTexture(new RenderTextureDescriptor(1,1,GraphicsFormat.R32G32B32A32_SFloat,0)
                { enableRandomWrite=true });
                owned.Add(value);
                if (!value.Create()) throw new Exception("Output creation failed.");
                return value;
            }
            var visibility=Output(); var signal=Output(); var world=Output();
            int kernel=reference.FindKernel("ReferenceReceivers");
            void Bind()
            {
                cmd.SetRayTracingAccelerationStructure(reference,kernel,"_ReferenceAcceleration",acceleration);
                cmd.SetComputeTextureParam(reference,kernel,"_ReferenceDepthTexture",depth);
                cmd.SetComputeTextureParam(reference,kernel,"_ReferenceGBuffer1",normal);
                cmd.SetComputeTextureParam(reference,kernel,"_ReferenceVisibility",visibility);
                cmd.SetComputeTextureParam(reference,kernel,"_BaselineShadowTexture",shadow);
                cmd.SetComputeTextureParam(reference,kernel,"_BaselineHistory",normal);
                cmd.SetComputeTextureParam(reference,kernel,"_BaselineSignal",signal);
                cmd.SetComputeTextureParam(reference,kernel,"_BaselineWorld",world);
                cmd.SetComputeIntParam(reference,"_BaselineHasHistory",0);
                foreach(string name in new[]{"_ReferenceScreenWidth","_ReferenceScreenHeight",
                    "_ReferenceGridWidth","_ReferenceGridHeight","_ReferencePixelStride"})
                    cmd.SetComputeIntParam(reference,name,1);
                cmd.SetComputeIntParam(reference,"_ReferenceROIOriginX",0);
                cmd.SetComputeIntParam(reference,"_ReferenceROIOriginY",0);
                cmd.SetComputeIntParam(reference,"_ReferenceRayCount",16);
                cmd.SetComputeFloatParam(reference,"_ReferenceTanAngularRadius",0);
                cmd.SetComputeFloatParam(reference,"_ReferenceRayMaxDistance",10);
                cmd.SetComputeVectorParam(reference,"_ReferenceNormalBias",new Vector4(.001f,.01f,0,0));
                cmd.SetComputeVectorParam(reference,"_ReferenceLightDirection",Vector3.forward);
                cmd.SetComputeVectorParam(reference,"_ReferenceSunBasisX",Vector3.right);
                cmd.SetComputeVectorParam(reference,"_ReferenceSunBasisY",Vector3.up);
                cmd.SetComputeMatrixParam(reference,"_ReferenceInvViewProjection",Matrix4x4.identity);
            }
            foreach(string route in new[]{"renderer_explicit_error", "renderer_explicit_standard", "mesh_config_readd"})
            foreach(var mode in new[]{RayTracingMode.DynamicTransform,RayTracingMode.DynamicGeometryManualUpdate})
            {
                var fixture = new GameObject("Temporary VSM " + mode) { hideFlags=HideFlags.HideInHierarchy };
                owned.Add(fixture);
                var mesh = new UnityEngine.Mesh { name="Temporary VSM update triangle" }; owned.Add(mesh);
                mesh.MarkDynamic();
                Vector3[] original = {new Vector3(-2,-2,.7f),new Vector3(4,-2,.7f),new Vector3(-2,4,.7f)};
                mesh.vertices=original; mesh.triangles=new[]{0,1,2}; mesh.RecalculateBounds(); mesh.RecalculateNormals();
                fixture.AddComponent<MeshFilter>().sharedMesh=mesh;
                var renderer=fixture.AddComponent<MeshRenderer>();
                renderer.sharedMaterial=route=="renderer_explicit_error" ? errorMaterial : standardMaterial;
                renderer.shadowCastingMode=ShadowCastingMode.TwoSided;
                renderer.rayTracingMode=mode;
                bool found=false;
                foreach(var candidate in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))
                    if(candidate==renderer) { found=true; break; }
                if(!found) throw new Exception("Temporary renderer is not discoverable; fixture invalid.");
                acceleration = new RayTracingAccelerationStructure(new RayTracingAccelerationStructure.Settings(
                    RayTracingAccelerationStructure.ManagementMode.Manual,RayTracingAccelerationStructure.RayTracingModeMask.Everything,-1));
                bool configRoute=route=="mesh_config_readd";
                int instanceHandle=-1;
                var submeshFlags=new RayTracingSubMeshFlags[mesh.subMeshCount];
                for(int sub=0;sub<submeshFlags.Length;sub++)
                    submeshFlags[sub]=RayTracingSubMeshFlags.Enabled|RayTracingSubMeshFlags.ClosestHitOnly;
                if(!configRoute) acceleration.AddInstance(renderer,submeshFlags,false,false,2);
                for(int step=0; step<3; step++)
                {
                    bool moved=step==1;
                    if(mode==RayTracingMode.DynamicTransform)
                        fixture.transform.position=moved ? new Vector3(10,0,0) : Vector3.zero;
                    else
                    {
                        var vertices=new Vector3[3];
                        for(int i=0;i<3;i++) vertices[i]=original[i]+(moved?new Vector3(10,0,0):Vector3.zero);
                        mesh.vertices=vertices; mesh.RecalculateBounds(); mesh.RecalculateNormals();
                    }
                    if(configRoute)
                    {
                        if(instanceHandle>=0) acceleration.RemoveInstance(instanceHandle);
                        var config=new RayTracingMeshInstanceConfig { mesh=mesh, meshLod=-1,subMeshIndex=0,
                            material=standardMaterial,mask=2,enableTriangleCulling=false,
                            subMeshFlags=RayTracingSubMeshFlags.Enabled|RayTracingSubMeshFlags.ClosestHitOnly,
                            rayTracingMode=RayTracingMode.DynamicGeometryManualUpdate };
                        instanceHandle=acceleration.AddInstance(in config,fixture.transform.localToWorldMatrix,null,0);
                        acceleration.UpdateInstanceGeometry(instanceHandle);
                    }
                    else
                    {
                        acceleration.UpdateInstanceTransform(renderer);
                        if(mode==RayTracingMode.DynamicGeometryManualUpdate) acceleration.UpdateInstanceGeometry(renderer);
                    }
                    if(acceleration.GetInstanceCount()!=1) throw new Exception("Expected exactly one fixture RTAS instance.");
                    cmd.BuildRayTracingAccelerationStructure(acceleration);
                    Bind(); cmd.DispatchCompute(reference,kernel,1,1,1);
                    Graphics.ExecuteCommandBuffer(cmd); cmd.Clear();
                    var readback=AsyncGPUReadback.Request(visibility); readback.WaitForCompletion();
                    if(readback.hasError) throw new Exception("Reference readback failed.");
                    var actual=readback.GetData<Vector4>()[0];
                    float expected=moved?1:0;
                    bool matches=true;
                    for(int channel=0;channel<4;channel++)
                        matches &= !float.IsNaN(actual[channel]) && Mathf.Abs(actual[channel]-expected)<=1e-6f;
                    report.AppendLine("route="+route+" mode="+mode+" step="+step+" expected="+expected+" actual="+actual
                        +(matches?" PASS":" FAIL"));
                    if(matches) passed++; else failed++;
                }
                acceleration.Dispose(); acceleration=null;
                UnityEngine.Object.DestroyImmediate(fixture);
                UnityEngine.Object.DestroyImmediate(mesh);
            }
            report.AppendLine("passed="+passed+" failed="+failed+"; three routes x two update modes x three poses."
                +" Renderer routes use explicit per-submesh flags; mesh config route removes/re-adds and marks geometry dirty."
                +" Only an individually passing complete blocked-clear-blocked route validates an update path.");
            report.AppendLine(failed==0?"PASS":"FAIL: inspect each route separately; failing routes cannot validate dynamic captures.");
            Directory.CreateDirectory(Path.GetDirectoryName(output));
            File.WriteAllText(output,report.ToString());
            result.Log(report.ToString());
        }
        catch(Exception error)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(output));
            File.WriteAllText(output,report.ToString()+"FAIL "+error);
            throw;
        }
        finally
        {
            cmd.Clear(); cmd.Dispose(); acceleration?.Dispose();
            for(int i=owned.Count-1;i>=0;i--) if(owned[i]!=null) UnityEngine.Object.DestroyImmediate(owned[i]);
        }
    }
}
